insert into public.dd_master_service_universe (canonical_sku,service_name,division,lifecycle_status,source_authority) values ('DNI-12A-027','Medical Courier & Healthcare Delivery','12','CANONICAL_ACTIVE','OWNER-APPROVED SERVICE ADDITION 2026-09-12'); update public.dd_master_service_universe set section='12-A Courier & Specialized Delivery', capability='Healthcare / Medical Logistics', service_family='Logistics, Courier & Asset Sourcing', task='Scheduled or on-demand transport of eligible medical supplies, specimens, records, and healthcare materials between authorized facilities, laboratories, pharmacies, providers, and related locations.', commercial_object_type='SERVICE', scope='Healthcare delivery and courier support for non-patient transport. Quote/contract only until material classes, packaging, handling, training, insurance and legal requirements are verified.', exclusions='No patient transportation; no medication dispensing; no clinical handling; no hazardous or infectious material transport until applicable requirements are verified.', dependencies='Customer/facility packaging and classification; route, temperature, chain-of-custody and delivery-window requirements; qualified courier capability.', customer_price='Quote / contract pricing — TBD pending underwriting', commercial_ownership='DANI DECLARES LLC', fulfillment_lane='PROVIDER_LED / QUALIFIED_LOGISTICS_NETWORK', provider_qualifications='Qualified courier/medical logistics provider; applicable PHMSA/hazmat training where required; chain-of-custody and temperature-control capability as applicable.', internal_cost='PENDING — actual route/labor/material/equipment economics required', provider_payout='PENDING — qualified provider rate required', margin_economics='PENDING — PASS 1 economics required', intake_requirements='Origin/destination, material type, packaging status, temperature requirement, quantity, pickup/delivery window, chain-of-custody requirement, facility contacts, special handling.', compliance_legal_boundaries='Healthcare courier work may involve HIPAA business-associate/conduit analysis depending on access to PHI; infectious substances and other regulated materials may trigger DOT/PHMSA requirements and training. Acceptance is material-specific and gated until verified.', sop='Medical courier SOP to be developed after scope classes and compliance requirements are validated.', workflow='Intake → classify material → verify acceptance → quote/contract → dispatch qualified courier → chain-of-custody → delivery confirmation → exception handling.', qa='Chain-of-custody, timestamps, delivery confirmation, temperature evidence where required, incident/exception log.', documentation='Route manifest, pickup/delivery record, chain-of-custody documentation, customer instructions, qualification evidence.', sla='Contract/SOW dependent.', ch01_rule='Not a standard resident offer; quote only if eligible.', ch02_rule='Eligible for facility logistics when validated.', ch03_rule='Generally not primary.', ch04_rule='Eligible for healthcare/commercial organizations subject to qualification.', ch05_rule='Eligible for institutional procurement subject to solicitation/compliance.', market_treatment='Georgia-first; route-specific pricing and compliance; no BUY NOW until PASS 1.', service_area_dispatch_zone='Georgia service area; route-specific mileage/handling may supersede standard dispatch rules.', version='2026-09-12-MEDICAL-COURIER-ADDITION', conflict_register='New service; does not replace Local Courier, Same-Day Courier, Priority Courier, Scheduled Route Delivery, or Chain-of-Custody Transport. Underwriting and compliance are intentionally pending.', cross_division_dependency_relationships='D12 logistics; D13 institutional procurement; D04 administrative coordination; D05 document/compliance support where applicable.', updated_at=now() where canonical_sku='DNI-12A-027'; insert into public.dd_governed_service_offers (master_record_id,canonical_sku,service_name,division,commercial_object_type,commercial_offer_status,fulfillment_gate_status,offer_basis,source_authority) select id,canonical_sku,service_name,division,commercial_object_type,'PENDING_RECONCILIATION','FULFILLMENT_GATED','New owner-approved medical courier service; quote/contract only pending economics, qualified provider coverage and compliance validation.','OWNER-APPROVED SERVICE ADDITION 2026-09-12' from public.dd_master_service_universe where canonical_sku='DNI-12A-027' and not exists (select 1 from public.dd_governed_service_offers where canonical_sku='DNI-12A-027');